sp_FiltrarEstoque	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_FiltrarEstoque`(\n\n    IN p_idEmpresa        INT,\n\n    IN p_idProduto        INT,\n\n    IN p_tipoMovimentacao VARCHAR(20),\n\n    IN p_dthInicio        DATETIME,\n\n    IN p_dthFim           DATETIME\n\n)\nBEGIN\n\n    SELECT\n\n        e.idEstoque,\n\n        e.idProduto,\n\n        p.nome  AS nomeProduto,\n\n        p.sku   AS skuProduto,\n\n        NULL    AS nomeCategoria,\n\n        e.quantidade,\n\n        e.estoqueMinimo,\n\n        IF(e.quantidade <= 0, 1, 0) AS estoqueCritico,\n\n        e.dthUltimaAtualizacao\n\n    FROM Estoque e\n\n    INNER JOIN Produto p ON p.idProduto = e.idProduto\n\n    WHERE e.idEmpresa  = p_idEmpresa\n\n      AND (p_idProduto IS NULL OR e.idProduto = p_idProduto)\n\n    ORDER BY p.nome;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
